def write_ts(fid, pathname, values, start_time, units, data_type):
    fid.put_ts(pathname, values=values, start_time=start_time, data_units=units, data_type=data_type, tzid="UTC")

def write_pd(fid, name, record):
    pathname = f"//{name}/STORAGE-FLOW///TABLE/"
    pdc = PairedDataContainer(pathname, (len(record["storage"]), 1))
    pdc.x_data = record["storage"]
    pdc.y_data = [record["flow"]]
    pdc.x_units = "THOU M3"
    pdc.x_type = "linear"
    pdc.y_units = "M3/S"
    pdc.y_type = "linear"
    pdc.y_labels = ["FLOW"]
    fid.put_pd(pdc)

if MAIN.exists():
    MAIN.unlink()
with HecDss.Open(str(MAIN), version=6, mode="rw") as fid:
    assert fid.version == 6
    for gage in sorted(RAIN):
        write_ts(fid, f"//{gage}/PRECIP-INC//1HOUR/GAGE/", RAIN[gage], "06MAY2005 0300", "MM", "PER-CUM")
    write_ts(fid, "//DisGage 1/FLOW//1HOUR/GAGE/", OBS, "06MAY2005 1600", "M3/S", "INST-VAL")
    for name in sorted(TABLES):
        write_pd(fid, name, TABLES[name])

with HecDss.Open(str(MAIN), mode="r") as fid:
    assert fid.version == 6
    for gage in sorted(RAIN):
        path = f"//{gage}/PRECIP-INC//1HOUR/GAGE/"
        ts = fid.read_ts(path, window=("06MAY2005 0300", "07MAY2005 1700"))
        got = list(ts.values)
        assert len(got) == len(RAIN[gage]), (gage, len(got))
        assert max(abs(float(a)-float(b)) for a,b in zip(got,RAIN[gage])) < 1e-3
    ts = fid.read_ts("//DisGage 1/FLOW//1HOUR/GAGE/", window=("06MAY2005 1600", "07MAY2005 1700"))
    got = list(ts.values)
    assert len(got) == len(OBS), len(got)
    assert max(abs(float(a)-float(b)) for a,b in zip(got,OBS)) < 1e-3
    for name, rec in TABLES.items():
        df = fid.read_pd(f"//{name}/STORAGE-FLOW///TABLE/")
        assert len(df.index) == len(rec["storage"])
        assert abs(float(df.index[-1]) - float(rec["storage"][-1])) < 1e-3

shutil.copy2(MAIN, OUT / "Manual_Calibration.dss")
shutil.copy2(MAIN, OUT / "Auto_Calibration.dss")
report = ["HEC-DSS validation: PASS", "DSS version: 6", "Student: 820504014", "Event: 2", "Scale factor: 0.95", "Rainfall records: 7", "Observed flow records: 1", "Paired-data records: 6", "Observed peak: 284.05 M3/S"]
(OUT / "DSS_VALIDATION.txt").write_text("\n".join(report) + "\n", encoding="utf-8")
print("\n".join(report))
